{"cmd": "mkdir -p /tmp/seccomp-probe && cat > /tmp/seccomp-probe/probe.c <<'EOF'
#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/ptrace.h>
#include <sys/syscall.h>
#include <sys/uio.h>
#include <linux/keyctl.h>

static void report(const char *name, long rc, int err, int expect_errno)
{
    int blocked = (rc == -1 && err == expect_errno);
    if (blocked)
        printf("%-20s BLOCKED rc=%ld errno=%d (%s)\n", name, rc, err, strerror(err));
    else if (rc == -1)
        printf("%-20s ALLOWED rc=-1 errno=%d (%s)\n", name, err, strerror(err));
    else
        printf("%-20s ALLOWED rc=%ld\n", name, rc);
}

int main(void)
{
    long rc;
    int err;
    char buf[16];

    printf("pid=%d seccomp-line:", getpid());
    fflush(stdout);
    {
        FILE *f = fopen("/proc/self/status", "r");
        if (f) {
            char line[256];
            while (fgets(line, sizeof line, f))
                if (!strncmp(line, "Seccomp", 7))
                    printf(" %s", line);
            fclose(f);
        }
    }

    errno = 0;
    rc = ptrace(PTRACE_TRACEME, 0, 0, 0);
    err = errno;
    report("ptrace", rc, err, EPERM);

    errno = 0;
    rc = syscall(SYS_keyctl, KEYCTL_GET_KEYRING_ID, KEY_SPEC_THREAD_KEYRING, 0);
    err = errno;
    report("keyctl", rc, err, EPERM);

    errno = 0;
    rc = syscall(SYS_add_key, "user", "probe", "x", 1, KEY_SPEC_THREAD_KEYRING);
    err = errno;
    report("add_key", rc, err, EPERM);

    errno = 0;
    rc = syscall(SYS_request_key, "user", "probe", NULL, KEY_SPEC_THREAD_KEYRING);
    err = errno;
    report("request_key", rc, err, EPERM);

    errno = 0;
    memset(buf, 0, sizeof buf);
    struct iovec local = { buf, sizeof buf };
    struct iovec remote = { buf, sizeof buf };
    rc = syscall(SYS_process_vm_writev, getpid(), &local, 1, &remote, 1, 0);
    err = errno;
    report("process_vm_writev", rc, err, EPERM);

    errno = 0;
    rc = syscall(SYS_getpid);
    err = errno;
    report("getpid (control)", rc, err, EPERM);
    return 0;
}
EOF
gcc -O1 -static -o /tmp/seccomp-probe/probe /tmp/seccomp-probe/probe.c && file /tmp/seccomp-probe/probe && ls -l /tmp/seccomp-probe/probe"}

